        c = new Owned();
    }

    function _run(address attacker, address newOwner) internal {
        vm.assume(attacker != address(this));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        vm.assume(ownerBefore != attacker);
        bool reverted;
        reverted = false;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.owner() == ownerBefore);
    }

